<?php
namespace Tests\Feature;
use App\Models\{BookingMobil,Mobil,Pelanggan,TestDrive,User,VehicleInventory};
use App\Services\{BookingMobilService,TestDriveService,VehicleInventoryService};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class BookingTestDriveStage4BTest extends TestCase
{
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function customer():User{return $this->user('pelanggan');}
 private function car():Mobil{return Mobil::where('status','tersedia')->firstOrFail();}
 private function inventory(Mobil $car):?VehicleInventory{return app(VehicleInventoryService::class)->find($car);}
 public function test_baseline_import_counts_are_present():void{$this->assertSame(2,BookingMobil::count());$this->assertSame(1,TestDrive::count());}
 public function test_customer_can_create_valid_booking():void{$u=$this->customer();$b=app(BookingMobilService::class)->create((int)$u->pelanggan->id_pelanggan,$this->car()->id_mobil,'QA');$this->assertSame('menunggu',$b->status);}
 public function test_guest_is_blocked_from_booking_and_test_drive():void{$this->get('/pelanggan/booking-mobil')->assertRedirect('/login');$this->get('/pelanggan/test-drive')->assertRedirect('/login');}
 public function test_customer_cannot_spoof_customer_id():void{$u=$this->customer();$this->withoutMiddleware()->actingAs($u)->post('/pelanggan/booking-mobil',['id_mobil'=>$this->car()->id_mobil,'id_pelanggan'=>999,'catatan'=>'spoof'])->assertRedirect();$this->assertSame($u->pelanggan->id_pelanggan,BookingMobil::latest('id_booking')->value('id_pelanggan'));}
 public function test_invalid_and_unavailable_cars_are_blocked():void{$svc=app(BookingMobilService::class);$u=$this->customer();$this->expectException(\RuntimeException::class);$svc->create($u->pelanggan->id_pelanggan,Mobil::where('status','terjual')->firstOrFail()->id_mobil,null);}
 public function test_duplicate_pending_booking_follows_native_rule():void{$u=$this->customer();$car=$this->car();$svc=app(BookingMobilService::class);$a=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$this->assertNotSame($a->id_booking,$b->id_booking);}
 public function test_admin_and_petugas_can_confirm_and_mobile_becomes_booked():void{$u=$this->customer();$car=$this->car();$inventory=$this->inventory($car);$before=$inventory?app(VehicleInventoryService::class)->reserveCount($car):null;$svc=app(BookingMobilService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$svc->confirm($b->id_booking,(int)app(BookingMobilService::class)->actorPetugasId($this->user('petugas')->id_user));$this->assertSame('dikonfirmasi',$b->fresh()->status);if($inventory){$this->assertSame($before+1,app(VehicleInventoryService::class)->reserveCount($car));}else{$this->assertSame('dibooking',$car->fresh()->status);}}
 public function test_second_confirmation_is_rejected_by_locked_unit():void{$u=$this->customer();$car=$this->car();$inventory=$this->inventory($car);$svc=app(BookingMobilService::class);$a=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$svc->confirm($a->id_booking,1);if($inventory&&(int)$inventory->stock_total-(int)$inventory->sold_units-app(VehicleInventoryService::class)->reserveCount($car)>0){$svc->confirm($b->id_booking,1);$this->assertSame('dikonfirmasi',$b->fresh()->status);}else{$this->expectException(\RuntimeException::class);$svc->confirm($b->id_booking,1);}}
 public function test_customer_cancel_unlocks_booked_mobile():void{$u=$this->customer();$car=$this->car();$svc=app(BookingMobilService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$svc->confirm($b->id_booking,1);$svc->cancel($b->id_booking,$u->pelanggan->id_pelanggan);$this->assertSame('dibatalkan',$b->fresh()->status);$this->assertSame('tersedia',$car->fresh()->status);}
 public function test_reject_is_not_an_allowed_booking_transition():void{$this->expectException(\Error::class);app(BookingMobilService::class)->reject(1);}
 public function test_expired_booking_is_marked_and_unlocks_unit():void{$u=$this->customer();$car=$this->car();$svc=app(BookingMobilService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);$b->update(['tanggal_expired'=>now()->subMinute()]);$svc->expire();$this->assertSame('kadaluarsa',$b->fresh()->status);}
 public function test_customer_cannot_open_another_customer_booking():void{$rows=BookingMobil::whereNotNull('id_pelanggan')->get();$this->assertGreaterThanOrEqual(2,$rows->count());$u=$this->customer();$other=$rows->first(fn($b)=>$b->id_pelanggan!==$u->pelanggan->id_pelanggan);$this->actingAs($u)->get('/pelanggan/booking-mobil/'.$other->id_booking)->assertForbidden();}
 public function test_customer_can_create_future_test_drive():void{$u=$this->customer();$d=app(TestDriveService::class)->create($u->pelanggan->id_pelanggan,$this->car()->id_mobil,now()->addDay()->toDateString(),'10:00','Showroom','QA');$this->assertSame('menunggu',$d->status);}
 public function test_past_test_drive_is_blocked():void{$this->expectException(\RuntimeException::class);$u=$this->customer();app(TestDriveService::class)->create($u->pelanggan->id_pelanggan,$this->car()->id_mobil,now()->subDay()->toDateString(),'10:00',null,null);}
 public function test_test_drive_does_not_change_mobile_status():void{$u=$this->customer();$car=$this->car();app(TestDriveService::class)->create($u->pelanggan->id_pelanggan,$car->id_mobil,now()->addDay()->toDateString(),'10:00',null,null);$this->assertSame('tersedia',$car->fresh()->status);}
 public function test_native_allows_same_test_drive_slot_without_new_conflict_rule():void{$u=$this->customer();$car=$this->car();$svc=app(TestDriveService::class);$a=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,now()->addDay()->toDateString(),'10:00',null,null);$b=$svc->create($u->pelanggan->id_pelanggan,$car->id_mobil,now()->addDay()->toDateString(),'10:00',null,null);$this->assertNotSame($a->id_test_drive,$b->id_test_drive);}
 public function test_test_drive_approve_reject_cancel_complete_transitions():void{$u=$this->customer();$svc=app(TestDriveService::class);$a=$svc->create($u->pelanggan->id_pelanggan,$this->car()->id_mobil,now()->addDay()->toDateString(),'10:00',null,null);$svc->approve($a->id_test_drive,1);$svc->complete($a->id_test_drive,1);$this->assertSame('selesai',$a->fresh()->status);$b=$svc->create($u->pelanggan->id_pelanggan,$this->car()->id_mobil,now()->addDay()->toDateString(),'11:00',null,null);$svc->reject($b->id_test_drive,1);$this->assertSame('ditolak',$b->fresh()->status);}
 public function test_customer_cannot_open_another_customer_test_drive():void{$u=$this->customer();$other=Pelanggan::where('id_pelanggan','<>',$u->pelanggan->id_pelanggan)->whereNotNull('id_user')->firstOrFail()->user;$td=app(TestDriveService::class)->create($other->pelanggan->id_pelanggan,$this->car()->id_mobil,now()->addDay()->toDateString(),'12:00',null,null);$this->actingAs($u)->get('/pelanggan/test-drive/'.$td->id_test_drive)->assertForbidden();}
 public function test_role_authorization_for_operations():void{$this->actingAs($this->customer())->get('/admin/booking-mobil')->assertForbidden();$this->actingAs($this->user('petugas'))->get('/petugas/booking-mobil')->assertOk();$this->actingAs($this->user('admin'))->get('/admin/test-drive')->assertOk();}
 public function test_booking_failure_leaves_mobile_and_booking_consistent():void{$u=$this->customer();$car=$this->car();$inventory=$this->inventory($car);$b=app(BookingMobilService::class)->create($u->pelanggan->id_pelanggan,$car->id_mobil,null);if($inventory){$inventory->update(['sold_units'=>$inventory->stock_total]);}else{$car->update(['status'=>'terjual']);}try{app(BookingMobilService::class)->confirm($b->id_booking,1);}catch(\Throwable $e){}$this->assertSame('menunggu',$b->fresh()->status);$this->assertSame($inventory?'tersedia':'terjual',$car->fresh()->status);}
 public function test_booking_and_test_drive_listing_eager_loads_relations():void{$this->actingAs($this->user('petugas'));$this->get('/petugas/booking-mobil')->assertOk();$this->get('/petugas/test-drive')->assertOk();}
 public function test_regression_auth_and_previous_modules_remain_available():void{$this->get('/login')->assertOk();$this->get('/mobil')->assertOk();$this->actingAs($this->user('admin'))->get('/admin/inventory/stok')->assertOk();}
}
